using System.Globalization;
using System.Text.Json;
using CustSearch.Application.AlertsRealtime;
using CustSearch.Application.Authorization;
using CustSearch.Application.ReportsExports;
using CustSearch.Domain.Entities;
using CustSearch.Domain.Enums;
using CustSearch.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Options;

namespace CustSearch.Infrastructure.ReportsExports;

/// <summary>Lease-based bounded export worker with server-side authorization revalidation and durable SignalR events.</summary>
public sealed class ExportJobProcessor(CustSearchDbContext db,IReportQueryRepository queries,IExportFileStore files,TimeProvider clock,IOptions<ReportsExportsOptions>options):IExportJobProcessor
{
    private static readonly JsonSerializerOptions JsonOptions=new(JsonSerializerDefaults.Web);private readonly ReportsExportsOptions settings=options.Value;
    public async Task<ExportProcessResult>ProcessDueAsync(int batchSize=10,CancellationToken ct=default){batchSize=Math.Clamp(batchSize,1,50);var ids=await db.ExportJobs.AsNoTracking().Where(x=>x.Status==ExportJobStatus.Queued&&x.ExpiresUtc>clock.GetUtcNow().UtcDateTime).OrderBy(x=>x.CreatedUtc).Select(x=>x.Id).Take(batchSize).ToListAsync(ct).ConfigureAwait(false);var claimed=0;var completed=0;var failed=0;foreach(var id in ids){var lease=Guid.NewGuid();var now=clock.GetUtcNow().UtcDateTime;var updated=await db.ExportJobs.Where(x=>x.Id==id&&x.Status==ExportJobStatus.Queued).ExecuteUpdateAsync(setters=>setters.SetProperty(x=>x.Status,ExportJobStatus.Processing).SetProperty(x=>x.Progress,(byte)1).SetProperty(x=>x.StartedUtc,x=>x.StartedUtc??now).SetProperty(x=>x.LeaseId,lease).SetProperty(x=>x.LeaseExpiresUtc,now.AddSeconds(settings.LeaseSeconds)).SetProperty(x=>x.AttemptCount,x=>x.AttemptCount+1).SetProperty(x=>x.Error,(string?)null),ct).ConfigureAwait(false);if(updated==0)continue;claimed++;db.ChangeTracker.Clear();var job=await db.ExportJobs.SingleAsync(x=>x.Id==id,ct).ConfigureAwait(false);try{await RevalidateAsync(job,ct).ConfigureAwait(false);await PublishAsync(job,"export.progress",10,$"Export {job.Id} is processing.",ct).ConfigureAwait(false);var filter=JsonSerializer.Deserialize<ReportFilter>(job.FilterJson,JsonOptions)?.Normalize()??throw new ReportExportException("Stored export filter is invalid.",ReportExportFailureKind.Validation);var stores=JsonSerializer.Deserialize<long[]>(job.AuthorizedStoreIdsJson,JsonOptions)??[];var all=new List<ReportDataRow>();long total=0;var page=1;while(all.Count<settings.MaximumExportRows){var request=filter with{Page=page,PageSize=Math.Min(500,settings.MaximumExportRows-all.Count)};var result=job.TenantId.HasValue?await queries.QueryTenantAsync(job.TenantId.Value,job.ReportType,stores,request,ct).ConfigureAwait(false):await queries.QueryPlatformAsync(job.ReportType,request,ct).ConfigureAwait(false);total=result.TotalRows;all.AddRange(result.Rows);if(result.Rows.Count<request.PageSize||all.Count>=total)break;page++;var progress=(byte)Math.Min(85,10+(all.Count*75/Math.Max(1,Math.Min(total,settings.MaximumExportRows))));job.ReportProgress(progress,lease);await db.SaveChangesAsync(ct).ConfigureAwait(false);}var bounded=new ReportResultView(job.ReportType,filter.FromUtc,filter.ToUtc,1,all.Count,total,all);var stored=await files.SaveAsync(job.Id,job.Format,bounded,ct).ConfigureAwait(false);job.Complete(stored.Path,stored.FileName,stored.ContentType,lease,clock.GetUtcNow().UtcDateTime);await PublishAsync(job,"export.completed",100,$"Export {job.Id} completed and is available until {job.ExpiresUtc:O}.",ct).ConfigureAwait(false);Audit(job,"ExportCompleted",new{job.Id,job.Format,Rows=all.Count,TotalRows=total,Bounded=all.Count<total});await db.SaveChangesAsync(ct).ConfigureAwait(false);completed++;}catch(Exception exception)when(exception is not OperationCanceledException){var error=$"{exception.GetType().Name}: export processing failed.";job.Fail(error,lease,clock.GetUtcNow().UtcDateTime);await PublishAsync(job,"export.failed",0,$"Export {job.Id} failed. Retry is available while the job is retained.",ct).ConfigureAwait(false);Audit(job,"ExportFailed",new{job.Id,ErrorCategory=exception.GetType().Name});await db.SaveChangesAsync(ct).ConfigureAwait(false);failed++;}db.ChangeTracker.Clear();}return new(claimed,completed,failed);}
    public async Task<int>ExpireDueAsync(int batchSize=50,CancellationToken ct=default){batchSize=Math.Clamp(batchSize,1,200);var now=clock.GetUtcNow().UtcDateTime;var jobs=await db.ExportJobs.Where(x=>x.ExpiresUtc<=now&&x.Status!=ExportJobStatus.Expired).OrderBy(x=>x.ExpiresUtc).Take(batchSize).ToListAsync(ct).ConfigureAwait(false);foreach(var job in jobs){if(job.FilePath is not null)try{await files.DeleteAsync(job.FilePath,ct).ConfigureAwait(false);}catch(ReportExportException exception)when(exception.Kind==ReportExportFailureKind.NotFound){}job.Expire(now);Audit(job,"ExportExpired",new{job.Id,job.ExpiresUtc,FileRemoved=true});}await db.SaveChangesAsync(ct).ConfigureAwait(false);return jobs.Count;}
    private async Task RevalidateAsync(ExportJob job,CancellationToken ct){var user=await db.UserAccounts.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==job.RequestedByUserId&&x.IsActive,ct).ConfigureAwait(false)??throw new ReportExportException("Export requester is no longer active.",ReportExportFailureKind.Forbidden);if(user.TenantId!=job.TenantId)throw new ReportExportException("Export tenant authorization changed.",ReportExportFailureKind.Forbidden);var permission=job.TenantId.HasValue?PermissionCatalog.Operations.ReportsExport:PermissionCatalog.Platform.ReportsExport;var granted=await db.UserRoles.AsNoTracking().Where(x=>x.UserId==user.Id&&x.Role.IsActive).SelectMany(x=>x.Role.RolePermissions).AnyAsync(x=>x.Permission.IsActive&&x.Permission.Name==permission,ct).ConfigureAwait(false);if(!granted)throw new ReportExportException("Export permission was revoked.",ReportExportFailureKind.Forbidden);if(job.TenantId.HasValue){var stores=JsonSerializer.Deserialize<long[]>(job.AuthorizedStoreIdsJson,JsonOptions)??[];var current=await db.UserStoreAssignments.AsNoTracking().Where(x=>x.TenantId==job.TenantId&&x.UserId==job.RequestedByUserId&&x.Store.IsActive).Select(x=>x.StoreId).ToListAsync(ct).ConfigureAwait(false);if(stores.Any(x=>!current.Contains(x)))throw new ReportExportException("Export store authorization changed.",ReportExportFailureKind.Forbidden);}}
    private async Task PublishAsync(ExportJob job,string eventName,byte progress,string message,CancellationToken ct){if(!job.TenantId.HasValue||!job.AlertId.HasValue)return;var alert=await db.Alerts.SingleAsync(x=>x.Id==job.AlertId&&x.TenantId==job.TenantId,ct).ConfigureAwait(false);if(eventName=="export.completed"){alert.Update(AlertSeverity.Info,$"Export {job.Id} completed",message,"ExportJob",job.Id.ToString(CultureInfo.InvariantCulture));alert.Resolve(clock.GetUtcNow().UtcDateTime);}else alert.Update(eventName=="export.failed"?AlertSeverity.Warning:AlertSeverity.Info,$"Export {job.Id}: {progress}%",message,"ExportJob",job.Id.ToString(CultureInfo.InvariantCulture));var now=clock.GetUtcNow().UtcDateTime;var correlation=$"export:{job.Id}";var realtime=RealtimeEvent.Create(job.TenantId.Value,null,alert.Id,eventName,1,correlation,$"{eventName}:{job.Id}:{job.AttemptCount}:{progress}",now);db.RealtimeEvents.Add(realtime);await db.SaveChangesAsync(ct).ConfigureAwait(false);var view=new AlertView(alert.Id,alert.AlertType,alert.StoreId,alert.Severity,alert.Title,alert.Message,alert.EntityType,alert.EntityId,alert.CreatedUtc,alert.AcknowledgedUtc,alert.AcknowledgedByUserId,alert.ResolvedUtc,alert.Status,alert.CorrelationId,alert.DeduplicationKey);var payload=JsonSerializer.Serialize(new AlertRealtimeEventV1(realtime.Id,eventName,1,now,job.TenantId.Value,null,correlation,view),JsonOptions);realtime.SetPayload(payload);db.NotificationOutbox.Add(NotificationOutboxMessage.Queue(job.TenantId.Value,null,alert.Id,realtime.Id,"SignalR",eventName,1,payload,correlation,$"signalr:{realtime.Id}",now));}
    private void Audit(ExportJob job,string action,object metadata){var now=clock.GetUtcNow().UtcDateTime;db.AuditLogs.Add(AuditLog.Record(job.TenantId,null,job.RequestedByUserId,"Worker",action,"ExportJob",job.Id.ToString(CultureInfo.InvariantCulture),null,JsonSerializer.Serialize(metadata,JsonOptions),null,null,$"export:{job.Id}",now));}
}
